CREATE TABLE IF NOT EXISTS cms_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL DEFAULT '',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO cms_settings(setting_key,setting_value) VALUES('site_name','VazinCMS'),('site_tagline','سایت جدید شما'),('default_locale','fa'),('contact_email','') ON CONFLICT(setting_key) DO NOTHING;
CREATE TABLE IF NOT EXISTS cms_pages (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,slug VARCHAR(190) NOT NULL,locale VARCHAR(10) NOT NULL DEFAULT 'fa',title VARCHAR(255) NOT NULL,body TEXT NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'draft',is_home SMALLINT NOT NULL DEFAULT 0,author_id BIGINT REFERENCES users(id),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(slug,locale));
CREATE TABLE IF NOT EXISTS cms_modules (module_key VARCHAR(80) PRIMARY KEY,name VARCHAR(160) NOT NULL,version VARCHAR(32),is_enabled SMALLINT NOT NULL DEFAULT 0,description TEXT,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO cms_modules(module_key,name,version,is_enabled,description) VALUES('travel','ماژول سفر','1.0.0',0,'مقصدها، خدمات، مقاله‌ها و درخواست سفر'),('visa','ماژول ویزا','1.0.0',0,'صفحات و جریان‌های اختصاصی خدمات ویزا') ON CONFLICT(module_key) DO NOTHING;
INSERT INTO schema_migrations(version) VALUES('4.1.0') ON CONFLICT(version) DO NOTHING;
